// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2018, "10-11", [{"author":"И. Иткин","question":"Какое слово лишнее по смыслу?","choices":["<em>терьер</em>","<em>эрдельтерьер</em>","<em>фокстерьер</em>","<em>интерьер</em>","<em>тойтерьер</em>."],"key":"Г","review":["Слова с похожим концом","Сопоставь значения слов, у которых одинаковая последовательность букв в конце.","Терьер, эрдельтерьер, фокстерьер и тойтерьер — названия собак. «Интерьер» обозначает внутреннее пространство и его обстановку."]},{"author":"М. Мирошниченко","question":"К какому из этих слов можно добавить <em>полу-</em>, чтобы получилось существующее слово?","choices":["<em>говорливый</em>","<em>шутливый</em>","<em>сметливый</em>","<em>драчливый</em>","<em>бодливый</em>."],"key":"Б","review":["Первая часть «полу-»","Вспомни выражение, которым называют слова, сказанные отчасти в шутку.","Можно сказать «ответил полушутливо» или «полушутливое замечание». «Полушутливый» — существующее слово со значением «отчасти шутливый»."]},{"author":"И. Рубанов","question":"Какое из слов в ответах (А)–(Г) не имеет отношения к мозгу?","choices":["<em>мозговитый</em>","<em>мозговой</em>","<em>промозглый</em>","<em>безмозглый</em>","все эти слова имеют отношение к мозгу."],"key":"В","review":["Слова с похожим корнем","Проверь, какие слова можно объяснить через «мозг», например «мозговой» — относящийся к мозгу.","«Промозглый» описывает холодную сырую погоду. Слова «мозговитый», «мозговой» и «безмозглый» связаны с мозгом."]},{"author":"Б. Иомдин","question":"Вот цитата из книги, вышедшей в Чехословакии: «сочетания с качественно-обстоятельственными наречиями <em>рано</em> и <em>поздно</em>, например, <em>рано утром</em>, <em>поздно вечером</em>, <em>поздно ночью</em>, <em>поздно утром</em>». Какое из этих словосочетаний встречается реже, чем другие?","choices":["<em>рано утром</em>","<em>поздно вечером</em>","<em>поздно ночью</em>","<em>поздно утром</em>","все эти словосочетания встречаются примерно одинаково часто."],"key":"Г","review":["Редкое сочетание времени","Подумай, что чаще всего значит «поздно», когда речь идёт о части суток, и как обычно называют позднюю часть утра.","О конце утра гораздо привычнее сказать «поздним утром», «к полудню» или «ближе к обеду». Среди данных сочетаний «поздно утром» встречается реже всего."]},{"author":"Б. Иомдин","question":"В какой паре слова меньше всего связаны по смыслу?","choices":["<em>дозор — дозорный</em>","<em>зазор — зазорный</em>","<em>обзор — обзорный</em>","<em>позор — позорный</em>","<em>узор — узорный</em>."],"key":"Б","review":["Существительное и признак","Попробуй объяснить каждое прилагательное через существительное из той же пары.","«Зазор» — промежуток между предметами, а «зазорный» значит «постыдный». В других парах связь прозрачна: например, узорный покрыт узорами."]},{"author":"А. Сомин","question":"<em>Больных в тот вечер у профессора было немного, и с приближением _________ ушёл последний</em> (Михаил Булгаков, «Мастер и Маргарита»). Как выглядит слово, которое мы пропустили?","choices":["<em>сумерки</em>","<em>сумерк</em>","<em>сумерков</em>","<em>сумерек</em>","<em>сумерок</em>."],"key":"Г","review":["Пропуск у Булгакова","Поставь вопрос «с приближением чего?». Нужно выбрать родительный падеж слова, у которого есть только формы множественного числа.","В именительном падеже это «сумерки», в родительном — «сумерек». Получается «с приближением сумерек»."]},{"author":"Л. Фёдорова","question":"В каком примере <em>пресс-</em> означает не то, что в остальных?","choices":["<em>пресс-центр</em>","<em>пресс-конференция</em>","<em>пресс-папье</em>","<em>пресс-служба</em>","<em>пресс-секретарь</em>."],"key":"В","review":["Значения «пресс-»","Определи, что в каждом случае связано с газетами или работой журналистов.","Пресс-центр, пресс-конференция, пресс-служба и пресс-секретарь работают с прессой. Пресс-папье прижимает бумаги и связано с глаголом «прессовать»."]},{"author":"С. Сай","question":"Какое прилагательное обычно употребляют по отношению к людям зрелого или пожилого возраста?","choices":["<em>младой</em>","<em>младший</em>","<em>молоденький</em>","<em>молодой</em>","<em>моложавый</em>."],"key":"Д","review":["Возраст и внешний вид","Найди слово, которое описывает человека, выглядящего моложе своего возраста.","«Моложавый» говорят о зрелом или пожилом человеке с молодым видом. Другие слова указывают на молодость, младшинство или меньший возраст."]},{"author":"Л. Фёдорова","question":"После чемпионата мира по футболу иностранные гости отмечали, что их мнение о России значительно улучшилось. Один из них сказал: <em>Наше мнение о России изменилось на 360 градусов</em>. А как следовало сказать?","choices":["<em>на 90 градусов</em>","<em>на 100 градусов</em>","<em>на 180 градусов</em>","<em>на 300 градусов</em>","иностранец сказал верно."],"key":"В","review":["Поворот мнения","Представь стрелку. Чтобы она указывала точно в противоположном направлении, достаточно половины полного оборота.","Полный поворот на 360° возвращает стрелку к исходному направлению. Направление поменяется на противоположное при повороте на 180°."]},{"author":"С. Сай","question":"Даны толкования существительных <em>кранио́лог</em>, <em>мартироло́г</em>, <em>перело́г</em> в перепутанном порядке:\nа) ‘оставленный без обработки и заросший участок земли, бывшей прежде под пашней’;\nб) ‘сборник рассказов о христианских мучениках или (перен.) перечень жертв преследований, гонений’;\nв) ‘специалист, занимающийся строением черепа человека или животных’.\nКаков правильный порядок этих толкований?","choices":["а, в, б","б, а, в","б, в, а","в, а, б","в, б, а."],"key":"Д","review":["Три словарных толкования","Узнай в «краниологе» часть, связанную с названием черепа, и сопоставь «мартиролог» с перечнем мучеников.","Краниолог изучает череп, мартиролог содержит сведения о мучениках, а перелог — заросший участок бывшей пашни. Порядок определений — «в, б, а»."]},{"author":"Г. Лайкауф и Е. Муравенко","question":"В каком из следующих предложений, взятых из Национального корпуса русского языка, частица <em>не</em> употреблена ошибочно и её следует заменить частицей <em>ни</em>?","choices":["<em>Обучаемые распознающие машины помогут криминалистам отыскивать преступников, как бы они не изменяли свою внешность</em>. (М. Гуревич, В. Литвиненко)","<em>Она только боялась, как бы он не спросил её вдруг, любит ли она Пушкина...</em> (Р. Фраерман)","<em>Да посмотри за младшим братом, как бы он не сбежал.</em> (А. Вампилов)","<em>Как бы он не подобрался к окну вплотную!..</em> (А. Волков)","<em>Макар под уздцы повёл Дичка на полосу, зорко следя, как бы он не рванулся назад и не наскочил бы на борону.</em> (С. Семёнов)"],"key":"А","review":["«Не» и «ни» после «как бы»","Поищи пример, в котором говорящий обещает результат независимо от обстоятельств. Другие фразы выражают опасение.","В первой цитате машины помогут опознать преступников при любых изменениях внешности. Для такого уступительного смысла пишут «как бы они ни изменяли»."]},{"author":"А. Сомин","question":"В Республике Беларусь проводится много игр-конкурсов. Например, конкурс по физике называется «Зубрёнок», по истории — «Кентаврик», по биологии — «Синица». А какое животное изображено на логотипе конкурса по информатике?","choices":["белка","сова","мышь","заяц","кошка."],"key":"В","review":["Логотип игры по информатике","Название игры можно связать одновременно с животным и с привычным устройством, которым управляют курсором.","Белорусская игра по информатике называется «Инфомышка». В названии обыгрывается компьютерная мышь, а на эмблеме изображена мышь."]},{"author":"Е. Бикмаев","question":"Даны названия единиц измерения физических величин с кратким пояснением в скобках и фамилии известных учёных. В каком случае их совпадение случайно?","choices":["<em>кулон</em> (количество электричества) — <em>Шарль Кулон</em>","<em>бэр</em> (биологический эквивалент рентгена) — <em>Карл Бэр</em>","<em>рентген</em> (доза радиоактивного облучения) — <em>Вильгельм Рентген</em>","<em>зиверт</em> (доза ионизирующего излучения) — <em>Рольф Зиверт</em>","<em>грей</em> (поглощённая доза ионизирующего излучения) — <em>Льюис Грей</em>."],"key":"Б","review":["Единицы и фамилии","Четыре названия даны в честь учёных, а одно образовано от букв слов, входящих в пояснение.","«Бэр» сокращает слова «биологический эквивалент рентгена». Совпадение с фамилией Карла Бэра случайно. Кулон, рентген, зиверт и грей названы в честь упомянутых учёных."]},{"author":"И. Иткин","question":"В спортивной газете вышла заметка о российском футболисте, играющем «во албанской ... лиге». «Во албанской» вместо «в албанской» — разумеется, ошибка. А какое слово мы пропустили в тексте заметки?","choices":["<em>профессиональной</em>","<em>высшей</em>","<em>первой</em>","<em>второй</em>","<em>третьей</em>."],"key":"Г","review":["«Во» перед названием лиги","Произнеси сочетания, переставив прилагательные: «в ... албанской лиге». Проверь, перед каким словом удобно сказать «во».","Говорят «во второй албанской лиге», потому что «второй» начинается с группы согласных «вт». Когда «албанской» переставили вперёд, предлог «во» сохранился по ошибке."]},{"author":"А. Пиперски","question":"Что значит сербское слово <em>полувреме</em>?","choices":["сутки","погода","час","срок","тайм."],"key":"Д","review":["Слово в сербском языке","Выдели часть «полу-» и подбери, в какой ситуации время делят на две условно равные части.","В спорте полувремя — одна из половин игры. По-русски её называют таймом."]},{"author":"А. Кухто и А. Пиперски","question":"Выберите фразу, в которой за подчёркнутым словом следует уточнение.","choices":["<em>Столовую свёклу высаживают три раза за сезон: <u>весной</u>, в июне и июле.</em>","<em><u>Летом</u>, в сентябре и декабре в итальянской Аосте проводятся ремесленные ярмарки.</em>","<em><u>Зимой</u>, в апреле и октябре оранжерея в чешском замке Леднице открыта только по выходным.</em>","<em>Государственный авиационный музей в Киеве закрывается в 19:00 <u>летом</u>, в октябре и в апреле.</em>","<em><u>Весной</u>, в сентябре и октябре, на австралийцев охотятся, казалось бы, безобидные сороки: птицы нападают на пешеходов, бегунов и велосипедистов.</em>"],"key":"Д","review":["Уточнение времени года","Проверь, входят ли названные месяцы в указанное время года в том месте, где происходят события.","В Австралии весна приходится на сентябрь, октябрь и ноябрь. Поэтому «в сентябре и октябре» уточняет «весной». В остальных примерах перечисляются разные части года."]},{"author":"А. Сомин","question":"<em>В задачи _________ части на железных дорогах входит, в частности, контроль вопросов режима труда и отдыха поездных работников, формирование поездных бригад, оформление маршрутных листов</em>. Какое слово мы пропустили?","choices":["<em>красивой</em>","<em>изящной</em>","<em>стильной</em>","<em>торжественной</em>","<em>нарядной</em>."],"key":"Д","review":["Железнодорожная служба","Подумай, какое слово называет распределение людей по обязанностям или сменам.","«Наряд» бывает заданием или распоряжением о работе. Нарядная часть организует выходы бригад и оформляет рабочие документы."]},{"author":"А. Сомин","question":"В каком из этих слов пропущена не буква <em>а</em>?","choices":["<em>к_рдиолог</em>","<em>к_рман</em>","<em>к_рдинально</em>","<em>к_ртавить</em>","во всех словах пропущена буква <em>а</em>."],"key":"Д","review":["Гласная в пропуске","Восстанови каждое слово по его значению. Особенно внимательно проверь «к_рдинально» в значении «коренным образом».","Пишут «кардиолог», «карман», «кардинально» и «картавить». Во всех четырёх словах пропущено «а»."]},{"author":"Б. Иомдин","question":"Даны пять толкований из словаря Даля. Какое слово не устарело и употребляется в том же значении до сих пор?","choices":["<em>Статейчатое сочинение, написанное статьями, параграфами.</em>","<em>Статист, статистка, актёр, актриса без речей, немой лицедей.</em>","<em>Статистика — наука о силе и богатстве государства.</em>","<em>Статьё — бытие ставшего, сотворённого, конченного.</em>","<em>Статья — что сталось, состоялось.</em>"],"key":"Б","review":["Значения у Даля","Сопоставь старые толкования с возможными современными значениями. Ищи слово, которое всё ещё так употребляют в театре или кино.","«Статист» по-прежнему может означать исполнителя роли без реплик. Значения «статьи», «статья», «статьё» и «статистика» изменились или вышли из употребления."]},{"author":"И. Иткин","question":"Одна из строф стихотворения испанского поэта Бартоломе Торреса Наарро «Мне выпала в жизни такая дорога...» (перевод Анатолия Гелескула) часто цитируется в таком виде:\n<em>При жизни покоюсь, покоя не зная,\nлежит моё время без тени движенья,\nбессмертием тешится слава земная,\nи празднует сердце свои пораженья...</em>\nПриведённый текст содержит опечатку, существенно искажающую смысл написанного. Какое слово необходимо исправить, чтобы стихотворение приобрело изначальный вид?","choices":["<em>лежит</em>","<em>время</em>","<em>тени</em>","<em>тешится</em>","<em>празднует</em>."],"key":"А","review":["Опечатка в стихотворении","Ищи два сходных по написанию глагола, у которых разные значения. Здесь речь о ходе времени.","В подлинном тексте «летит моё время». В замене «летит» на «лежит» поменялась одна буква и появилась идея неподвижности вместо быстрого хода времени."]},{"author":"А. Пиперски","question":"Слова <em>золото</em>, <em>йод</em>, <em>медь</em>, <em>олово</em>, <em>сера</em> и <em>фосфор</em> в абсолютном большинстве словарей русского языка следуют именно в таком порядке. А вот в «Грамматическом словаре русского языка» А. А. Зализняка они располагаются так: <em>сера</em>, <em>йод</em>, <em>олово</em>, <em>золото</em>, <em>фосфор</em>, <em>медь</em>. Где в этом словаре стоит слово <em>бор</em>?","choices":["до слова <em>сера</em>","между словами <em>сера</em> и <em>олово</em>","между словами <em>олово</em> и <em>золото</em>","между словами <em>золото</em> и <em>фосфор</em>","между словами <em>фосфор</em> и <em>медь</em>."],"key":"Г","review":["Сортировка в словаре","Прочти слова справа налево и посмотри, как упорядочены их последние, а затем предпоследние буквы.","«Золото» заканчивается на «о», «бор» и «фосфор» — на «р». Если идти с конца, «роб» от слова «бор» предшествует «роф» от «фосфор». Значит, «бор» стоит между «золото» и «фосфор»."]},{"author":"И. Иткин","question":"Глагол <em>обязываться</em> спрягается необычно: <em>обязуюсь</em>, <em>обязуешься</em> и т. д. В современном русском языке сохранились следы того, что раньше подобным образом мог спрягаться и ... .","choices":["глагол <em>связывать</em>","глагол <em>отвязывать</em>","глагол <em>привязывать</em>","глагол <em>перевязывать</em>","любой из глаголов, перечисленных в (А)–(Г)."],"key":"А","review":["Старинное спряжение","Вспомни слово «связующий». Подумай, какую старую личную форму можно из него восстановить.","«Связующий» сохраняет основу «связую-». Она указывает на старую форму «связую» от «связывать», сопоставимую с «обязуюсь»."]},{"author":"Л. Фёдорова","question":"В какой паре слова не входят в одно и то же устойчивое выражение?","choices":["<em>Сенька — шапка</em>","<em>Тришка — кафтан</em>","<em>Алёнушка — козлёночек</em>","<em>Макар — телята</em>","<em>Фома — Ерёма</em>."],"key":"В","review":["Имена в выражениях","Для каждой пары попробуй восстановить пословицу, фразеологизм или обычную парную формулу.","Есть «по Сеньке шапка», «Тришкин кафтан», «куда Макар телят не гонял», «про Фому, а он про Ерёму». Алёнушка и козлёночек встречаются в сказке, но не составляют устойчивого выражения."]},{"author":"И. Иткин","question":"В 1824 году А. С. Пушкин в письме обращается к брату Льву с просьбой: <em>Напиши мне нечто о Карамзине, ой, ...</em> .","choices":["<em>ай</em>","<em>ах</em>","<em>ох</em>","<em>ух</em>","<em>ых</em>."],"key":"Д","review":["Что Пушкин дописал в письме","Заметь, что «Карамзине» можно переделать в «Карамзиных» и тем самым расширить просьбу с одного человека на семью.","Пушкин в шутку поправляет окончание, не переписывая всю фамилию. В письме стоит «о Карамзине, ой, ых»."]},{"author":"А. Пиперски","question":"Существительные II склонения в древнерусском языке в дательном падеже множественного числа имели не окончание -<em>ам</em>, а окончание -<em>омъ</em>: например, сейчас мы говорим <em>столам</em>, <em>числам</em>, а раньше говорили <em>столомъ</em>, <em>числомъ</em>. От какого существительного в русском языке образовано наречие, которое сохраняет след этого окончания?","choices":["<em>год</em>","<em>море</em>","<em>знак</em>","<em>слово</em>","<em>дело</em>."],"key":"Д","review":["След древнего окончания","Поищи старую форму существительного внутри наречия, которое сегодня пишется слитно.","В «поделом» сохранилось прежнее сочетание «по деломъ», то есть «по делам». Старое окончание принадлежало слову «дело»."]},{"author":"П. Аркадьев","question":"В каких строках приведённого фрагмента стихотворения Антона Дельвига «Элегия» (1821 или 1822) встречается <em>е</em> под ударением?\n<em>Когда ещё я не пил слёз\nИз чаши бытия, —\nЗачем тогда, в венке из роз,\nК теням не отбыл я!</em>","choices":["только в третьей","только в третьей и четвёртой","только в первой и третьей","во всех, кроме второй","ни в одной."],"key":"В","review":["Ударные слоги в «Элегии»","Прочитай строки по ритму ямба, выделяя чётные слоги. Проверь, куда в первой и четвёртой строках попадают слова «не» и «теням».","В первой строке на сильном месте «не́», в третьей — «заче́м» и «венке́». Во второй строке ударны «ча́ши», «бытия́», в четвёртой — «теня́м», «о́тбыл», «я́»."]},{"author":"С. Сай","question":"В русском языке существует разговорная частица, используемая для выражения удивления или укоризны. Это слово исторически восходит к форме второго лица единственного числа глагола. Какого?","choices":["<em>баять</em>","<em>видеть</em>","<em>знать</em>","<em>лить</em>","<em>чуять</em>."],"key":"Б","review":["Частица из глагола","Вспомни, как говорят при удивлении или укоре: «Ишь ты!» Какой глагол мог предшествовать этому возгласу?","«Ишь» исторически связано с «видишь» — формой второго лица глагола «видеть». Частица прошла путь от призыва обратить внимание к выражению удивления."]},{"author":"С. Сай","question":"Один лингвист занимался проблемой выражения пространственных отношений в разных языках и составил для русского языка таблицу, фрагмент которой приводится справа. Как заполнить пропуски, обозначенные символами * и **?","choices":["под5, к3","под6, у4","под5, у4","под5; за4","под6, к3."],"key":"А","review":["Таблица направлений","Прочитай каждую колонку как ряд «где?», «куда?», «откуда?». Числа указывают падеж, который употребляется с предлогом.","«Под столом» отвечает на «где?» и требует творительного падежа, пятого. «К столу» отвечает на «куда?» и требует дательного, третьего. В пропусках получаются «под5» и «к3»."],"figure":{"condition":{"src":"assets/medvezhonok/2018/10-11-28-table.svg","alt":"Таблица с тремя строками и четырьмя столбцами. Первая строка: в6, на6, звёздочка, у2. Вторая строка: в4, на4, под4, две звёздочки. Третья строка: из2, с2, из-под2, от2.","detailSrc":"assets/medvezhonok/2018/10-11-28-table.svg"}}},{"author":"С. Сай","question":"Для глагола <em>тонуть</em> можно подобрать исторически родственный глагол <em>топить</em>, имеющий значение ‘делать так, чтобы…’. А в каком случае исторически родственный глагол с таким значением подобрать нельзя?","choices":["<em>гнить</em>","<em>есть</em>","<em>пить</em>","<em>смеяться</em>","<em>стоять</em>."],"key":"Б","review":["Глаголы со смыслом причины","Подбирай для каждого глагола действие другого лица: «заставить пить» — «поить», «заставить смеяться» — «смешить».","Есть пары «гнить — гноить», «пить — поить», «смеяться — смешить», «стоять — ставить». «Кормить» значит давать есть, но с «есть» исторически не связано."]},{"author":"А. Пиперски","question":"Восстановите слово, пропущенное в шестистишии из ранней редакции стихотворения «Пятистопные ямбы» Николая Гумилёва:\n<em>Мне золочёный ______ вручил Вергилий,\nА строгий Дант — гусиное перо,\nИ мне не надо ангельских воскрылий,\nЧужое отвергаю я добро,\nЯ лилия простая между лилий,\nСредь серебра я только серебро.</em>","choices":["<em>стих</em>","<em>ритм</em>","<em>слог</em>","<em>стиль</em>","<em>ямб</em>."],"key":"Г","review":["Поэтический подарок","Заметь, что второй поэт вручает письменную принадлежность. Какое слово тоже могло в старину называть предмет для письма?","«Стиль» может значить палочку для письма на воске, а также манеру письма. Поэтому золочёный стиль образует смысловую пару с гусиным пером Данте."]}], {"year":2018,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2018-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
